import yazl from "yazl";
import { mkdir } from "node:fs/promises";
import { createWriteStream } from "node:fs";
import { dirname } from "node:path";
export async function buildFixtureEpub(path:string){const zip=new yazl.ZipFile();zip.addBuffer(Buffer.from("application/epub+zip"),"mimetype",{compress:false});const files={"META-INF/container.xml":`<?xml version="1.0"?><container><rootfiles><rootfile full-path="OEBPS/content.opf"/></rootfiles></container>`,"OEBPS/content.opf":`<package><metadata><title>Fixture</title></metadata><manifest><item id="chapter" href="chapter.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="chapter"/></spine></package>`,"OEBPS/chapter.xhtml":`<html xmlns="http://www.w3.org/1999/xhtml"><body><p>Hello <em>world</em>.</p></body></html>`};for(const [name,content] of Object.entries(files))zip.addBuffer(Buffer.from(content),name);await mkdir(dirname(path),{recursive:true});await new Promise<void>((resolve,reject)=>{const stream=createWriteStream(path);stream.on("error",reject).on("close",resolve);zip.outputStream.pipe(stream);zip.end();});return path;}
